import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import api from '../../services/api';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import iconUrl from 'leaflet/dist/images/marker-icon.png';
import iconShadow from 'leaflet/dist/images/marker-shadow.png';
import getMapStyle from '../../services/mapStyle';
export default {
  name: 'StoreAccountLocation',
  data() {
    return {
      latitude: null,
      longitude: null,
      address: '',
      mapInstance: null,
      markerInstance: null,
      hasKey: !!process.env.VUE_APP_MAPTILER_KEY,
      mapStyle: process.env.VUE_APP_MAP_STYLE || 'streets'
    };
  },
  async mounted() {
    await this.load();
    this.initMap();
  },
  methods: {
    async load() {
      try {
        const {
          data
        } = await api.get('/store/account/location');
        this.latitude = data.latitude ?? null;
        this.longitude = data.longitude ?? null;
        this.address = data.address || '';
      } catch (err) {
        console.error('Failed to load location', err);
      }
    },
    async initMap() {
      const hasKey = !!process.env.VUE_APP_MAPTILER_KEY;
      if (hasKey) {
        const style = getMapStyle(this.mapStyle);
        const center = Number.isFinite(this.latitude) && Number.isFinite(this.longitude) ? [this.longitude, this.latitude] : [120.9842, 14.5995];
        this.mapInstance = new maplibregl.Map({
          container: 'ownerMap',
          style,
          center,
          zoom: 12
        });
        if (Number.isFinite(this.latitude) && Number.isFinite(this.longitude)) {
          this.markerInstance = new maplibregl.Marker().setLngLat([this.longitude, this.latitude]).addTo(this.mapInstance);
        }
        this.mapInstance.on('click', e => {
          const {
            lng,
            lat
          } = e.lngLat;
          this.latitude = Number(lat.toFixed(6));
          this.longitude = Number(lng.toFixed(6));
          const pos = [this.longitude, this.latitude];
          if (this.markerInstance) {
            this.markerInstance.setLngLat(pos);
          } else {
            this.markerInstance = new maplibregl.Marker().setLngLat(pos).addTo(this.mapInstance);
          }
        });
        return;
      }
      // Leaflet fallback without API key (Carto tiles)
      L.Marker.prototype.options.icon = L.icon({
        iconUrl,
        shadowUrl: iconShadow
      });
      const centerArr = Number.isFinite(this.latitude) && Number.isFinite(this.longitude) ? [this.latitude, this.longitude] : [14.5995, 120.9842];
      this.mapInstance = L.map('ownerMap').setView(centerArr, 12);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
        attribution: '© OpenStreetMap contributors © CARTO'
      }).addTo(this.mapInstance);
      if (Number.isFinite(this.latitude) && Number.isFinite(this.longitude)) {
        this.markerInstance = L.marker(centerArr).addTo(this.mapInstance);
      }
      this.mapInstance.on('click', e => {
        const lat = e.latlng.lat;
        const lng = e.latlng.lng;
        this.latitude = Number(lat.toFixed(6));
        this.longitude = Number(lng.toFixed(6));
        const pos = [this.latitude, this.longitude];
        if (this.markerInstance) {
          this.markerInstance.setLatLng(pos);
        } else {
          this.markerInstance = L.marker(pos).addTo(this.mapInstance);
        }
      });
    },
    switchStyle() {
      if (!this.hasKey || !this.mapInstance || !this.mapInstance.setStyle) return;
      this.mapInstance.setStyle(getMapStyle(this.mapStyle));
    },
    async save() {
      try {
        const payload = {
          latitude: this.latitude,
          longitude: this.longitude,
          address: this.address
        };
        await api.put('/store/account/location', payload);
        alert('Location saved');
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to save location');
      }
    }
  }
};
